def humano(s):
 s=str(s)
 for a,b in sorted(WORDS.items(),key=lambda v:-len(v[0])):s=re.sub(r'(?<![A-Za-zÁÉÍÓÚáéíóúñ])'+re.escape(a)+r'(?![A-Za-zÁÉÍÓÚáéíóúñ])',b,s)
 s=re.sub(r'(?<=\d)(kVA|kW|kV|daN|kgf|kg|mm|kN|mV|Hz|microstrain|pu|ohm|días|años|grados)\b',r' \1',s)
 s=re.sub(r'(?<=\d)(m|V|A|h)\b',r' \1',s)
 s=re.sub(r'(?<=[,;])(?=[A-Za-zÁÉÍÓÚáéíóúñ])',' ',s)
 return s
